public class InnerMessageTemplateSystemAttributesFactory(Action<Humidifier.Wisdom.MessageTemplateTypes.SystemAttributes> factoryAction = null) : SubResourceFactory<Humidifier.Wisdom.MessageTemplateTypes.SystemAttributes>
{

    internal InnerMessageTemplateSystemEndpointAttributesFactory CustomerEndpointFactory { get; set; }

    internal InnerMessageTemplateSystemEndpointAttributesFactory SystemEndpointFactory { get; set; }

    protected override Humidifier.Wisdom.MessageTemplateTypes.SystemAttributes Create()
    {
        var systemAttributesResult = CreateSystemAttributes();
        factoryAction?.Invoke(systemAttributesResult);

        return systemAttributesResult;
    }

    private Humidifier.Wisdom.MessageTemplateTypes.SystemAttributes CreateSystemAttributes()
    {
        var systemAttributesResult = new Humidifier.Wisdom.MessageTemplateTypes.SystemAttributes();

        return systemAttributesResult;
    }
    public override void CreateChildren(Humidifier.Wisdom.MessageTemplateTypes.SystemAttributes result)
    {
        base.CreateChildren(result);

        result.CustomerEndpoint ??= CustomerEndpointFactory?.Build();
        result.SystemEndpoint ??= SystemEndpointFactory?.Build();
    }

} // End Of Class

